import{_ as o,o as t,c as a,a5 as d}from"./chunks/framework.-jms6n7v.js";const f=JSON.parse('{"title":"Python changelog","description":"The history of the Python package darudb, newest first. Every package versions on its own and keeps its own history; choose another language in the sidebar for…","frontmatter":{"title":"Python changelog","order":1,"editLink":false,"outline":[2,3],"prev":{"text":"StoredSchema","link":"/types/python/stored-schema"},"next":{"text":"Comparison","link":"/compare"}},"headers":[{"level":2,"title":"Python package darudb","slug":"python-package-darudb","link":"#python-package-darudb","children":[{"level":3,"title":"darudb vNext (2026--)","slug":"darudb-vnext-2026","link":"#darudb-vnext-2026","children":[{"level":4,"title":"Added","slug":"added","link":"#added","children":[]},{"level":4,"title":"Changed","slug":"changed","link":"#changed","children":[]}]},{"level":3,"title":"darudb v1.4.0 (2026-10-29)","slug":"darudb-v1-4-0-2026-10-29","link":"#darudb-v1-4-0-2026-10-29","children":[{"level":4,"title":"Added","slug":"added-1","link":"#added-1","children":[]},{"level":4,"title":"Changed","slug":"changed-1","link":"#changed-1","children":[]}]},{"level":3,"title":"darudb v1.3.0 (2026-10-13)","slug":"darudb-v1-3-0-2026-10-13","link":"#darudb-v1-3-0-2026-10-13","children":[{"level":4,"title":"Added","slug":"added-2","link":"#added-2","children":[]},{"level":4,"title":"Changed","slug":"changed-2","link":"#changed-2","children":[]}]},{"level":3,"title":"darudb v1.2.0 (2026-10-11)","slug":"darudb-v1-2-0-2026-10-11","link":"#darudb-v1-2-0-2026-10-11","children":[{"level":4,"title":"Changed","slug":"changed-3","link":"#changed-3","children":[]},{"level":4,"title":"Fixed","slug":"fixed","link":"#fixed","children":[]}]},{"level":3,"title":"darudb v1.1.0 (2026-10-09)","slug":"darudb-v1-1-0-2026-10-09","link":"#darudb-v1-1-0-2026-10-09","children":[{"level":4,"title":"Breaking changes","slug":"breaking-changes","link":"#breaking-changes","children":[]},{"level":4,"title":"Added","slug":"added-3","link":"#added-3","children":[]},{"level":4,"title":"Changed","slug":"changed-4","link":"#changed-4","children":[]},{"level":4,"title":"Fixed","slug":"fixed-1","link":"#fixed-1","children":[]}]},{"level":3,"title":"darudb v1.0.0 (2026-10-07)","slug":"darudb-v1-0-0-2026-10-07","link":"#darudb-v1-0-0-2026-10-07","children":[{"level":4,"title":"Added","slug":"added-4","link":"#added-4","children":[]}]}]}],"relativePath":"changelog/python.md","filePath":"en/changelog/python.md","lastUpdated":null}'),n={name:"changelog/python.md"};function i(s,e,c,r,h,l){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="python-changelog" tabindex="-1">Python changelog <a class="header-anchor" href="#python-changelog" aria-label="Permalink to &quot;Python changelog&quot;">​</a></h1><p>The history of the Python package <code>darudb</code>, newest first. Every package versions on its own and keeps its own history; choose another language in the sidebar for its packages&#39; history.</p><h2 id="python-package-darudb" tabindex="-1">Python package <code>darudb</code> <a class="header-anchor" href="#python-package-darudb" aria-label="Permalink to &quot;Python package `darudb`&quot;">​</a></h2><h3 id="darudb-vnext-2026" tabindex="-1">darudb vNext (2026--) <a class="header-anchor" href="#darudb-vnext-2026" aria-label="Permalink to &quot;darudb vNext (2026--)&quot;">​</a></h3><h4 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>Cascading links: <code>darudb.field(link=User, cascade=True)</code> makes deleting the object the link names delete the object that holds the link, and so on down the chain, cycles included, in the same transaction, through <code>delete</code>, <code>delete_where</code>, their asynchronous forms and a migration&#39;s function. <code>delete</code> still returns whether the object it was given was there, and <code>delete_where</code> how many objects its query found. Only a link to one object of the collection itself cascades. An index on the field is how a delete finds the objects to take with it: without one, each delete reads the whole collection that links. <code>StoredField.cascade</code> reads the declaration back. A file with a cascading link is in object format 2, which earlier releases do not open.</li><li>Indexes on several fields, and on fields inside embedded objects: <code>@darudb.collection(&quot;people&quot;, indexes=[darudb.index(&quot;last&quot;, &quot;first&quot;, unique=True), darudb.index(F.home.city)])</code>. <code>darudb.index</code> takes 1 to 8 fields, each an attribute&#39;s name, a path such as <code>&quot;home.city&quot;</code> or an <code>F</code> path, which turn into the names the file stores. A query testing the first fields for equality and the next for a range reads one range of its entries, and one that sorts by the fields after them gets its objects in order. A unique one refuses two objects with the same values in every field, though any number may hold <code>None</code> in one. <code>StoredIndex</code> has <code>fields</code>, every field an index is on. Such an index needs object format 2.</li><li>Lists of embedded objects: a field annotated <code>list[Stop]</code>, where <code>Stop</code> is an <code>@darudb.embedded</code> class, holds a list of them and reads back as a list of instances. A path through it, <code>F.stops.city</code>, tests that field of each element, and a condition holds when it holds for any element; the attributes turn into the names the file stores, as they do through an embedded object. Such a list has no index and no sort, and its default is the empty list, <code>field(default_factory=list)</code>. It needs object format 2, as a date does.</li><li><code>datetime</code> fields: a date, kept to the microsecond. A field annotated <code>datetime</code> takes an aware <code>datetime</code>, whatever its time zone, and reads back as one in UTC; a naive <code>datetime</code> names no instant and is refused with <code>INVALID_ARGUMENT</code>. The conversion is whole <code>timedelta</code> arithmetic, never a float timestamp. A date can be a list&#39;s element, a default, an indexed field and a sort&#39;s, a query compares it with an aware <code>datetime</code>, in a condition, a parameter or <code>DATE &quot;2026-10-30T12:00:00Z&quot;</code> in the query language, and <code>min</code> and <code>max</code> give one. A date beyond the years a <code>datetime</code> holds, 1 to 9999, fails with <code>INVALID_ARGUMENT</code> when it is read. The first date a schema declares moves the file to object format 2, which releases of the package before this one do not open; <code>upgrade_format=False</code> refuses that with <code>INVALID_ARGUMENT</code>.</li><li><code>darudb.linked(Post, &quot;author&quot;, condition)</code> holds for an object that some object of the collection <code>Post</code> links to through its link field <code>author</code>, and that meets <code>condition</code> on <code>Post</code>&#39;s fields, if it is given: <code>users.find(darudb.linked(Post, &quot;author&quot;, F.year &gt;= 2020))</code>. <code>~</code> of it finds the objects nothing links to. The collection may be a class or a name; the link and the condition name its attributes, which the package turns into the names the file stores. It is <code>ANY posts.author (year &gt;= 2020)</code> in the query language.</li><li>Tests that ignore case: <code>Condition.ignore_case()</code> makes every test of <code>==</code>, <code>!=</code>, <code>is_in</code>, <code>contains</code>, <code>startswith</code> and <code>endswith</code> inside a condition compare strings by Unicode&#39;s simple case folding, as <code>IGNORE CASE</code> does in the query language: <code>users.find((F.name == &quot;kim&quot;).ignore_case())</code>. A test that orders, or one of a field holding no strings, fails with <code>INVALID_QUERY</code>. Every wheel&#39;s <code>THIRD_PARTY_NOTICES.txt</code> carries the licence notice of the Unicode data the folding comes from.</li><li><code>delete_where</code> and <code>update_where</code> on a write collection, and their <code>async</code> twins, delete or update every object a query finds, after its sort, offset and limit, and return how many there were: <code>users.update_where(F.age &lt; 18, active=False)</code>. The query is required, in any form <code>find</code> takes, with its parameters after it; <code>Query()</code> finds every object. An update by query is all or nothing: when one object is refused, by a unique value taken or an index entry too long, the objects changed before it are put back. It cannot set the primary key.</li><li>Aggregates: <code>sum</code>, <code>min</code>, <code>max</code> and <code>avg</code> on a collection, and their <code>async</code> twins, work out one value from a field of the objects a query finds, after its sort, offset and limit, with the query in any form <code>find</code> takes: <code>users.sum(&quot;age&quot;, F.age &gt; 18)</code>, <code>users.max(F.address.city, &quot;age &gt; $0&quot;, 18)</code>. The field is an attribute&#39;s name, a path through embedded objects and links, or an <code>F</code> path, and goes to the name the file stores. Nulls are left out; a sum of no values is 0 and the rest are <code>None</code>. A sum is exact, an <code>int</code> for an int field and a <code>float</code> for a float field, and a mean is a <code>float</code>.</li></ul><h4 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>The native module is built with its functions aligned to 64 bytes as well as its loops, so that where a hot function lands no longer depends on the rest of the build: in the engine&#39;s benchmark on an Apple M1 Max, a count through an index had run 12% slower after changes that left its code as it was, and it no longer does. It is about 3% larger for it.</li></ul><h3 id="darudb-v1-4-0-2026-10-29" tabindex="-1">darudb v1.4.0 (2026-10-29) <a class="header-anchor" href="#darudb-v1-4-0-2026-10-29" aria-label="Permalink to &quot;darudb v1.4.0 (2026-10-29)&quot;">​</a></h3><h4 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>plain</code> in <code>Database.backup</code> and <code>Database.backup_async</code>, which writes the copy with no encryption: the way to turn an encrypted database into a plain one, which put in the encrypted file&#39;s place opens without a key or a password. Auto-increment counters and the stored schema come across as they are. <code>plain</code> beside a <code>key</code> or a <code>password</code> fails with <code>INVALID_ARGUMENT</code>.</li></ul><h4 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>A query sorted by an indexed field, with an offset and nothing of its filter left to test on the objects it reads, skips the objects before its page by their keys, rather than reading each of them. A page of 50 objects after up to 98,703 others took 0.69 ms rather than 19 ms on an Apple M1 Max.</li><li>A query whose filter has terms that indexes answer alone gathers the keys of the objects that meet them from the indexes, and combines them before it reads an object, when counting the indexes&#39; entries says that is cheaper: terms joined by <code>AND</code> meet, terms joined by <code>OR</code> join, a test through a link field with an index, such as <code>author.country == &quot;kr&quot;</code>, goes through the linked collection&#39;s index and then the link&#39;s, and a query sorted by an indexed field with a limit walks that index and takes only the gathered keys. In the benchmark&#39;s complex suite on an Apple M1 Max, a count with <code>OR</code> across two indexes took 92% less time, a count with conditions on two indexes 69% less, three conditions on two indexes sorted with a limit 39% less, the first 20 posts of authors in one country 93% less, a count through two links 93% less, and the first 20 posts with a tag sorted by another index 95% less.</li><li>A set of gathered keys that are all ints lying close together, as an auto-increment collection&#39;s keys are, is looked up through a bit for each int rather than a table of their hashes, and its keys are read once to find their order and their range. In the benchmark&#39;s complex suite on an Apple M1 Max, against the sets of keys above, the count with conditions on two indexes took 40% less time, the count through two links 33% less, the count with <code>OR</code> 27% less, three conditions sorted with a limit 19% less, the first 20 posts of authors in one country 17% less, and the first 20 posts with a tag 7% less.</li><li><code>CONTAINS</code> on a string searches the string&#39;s bytes with a searcher made once for the query, and checks the string is UTF-8 only where it finds the text, rather than checking and searching each string anew. A query that counts the posts whose text contains two words in a row, over 300,000 posts with no index, took 11% less time on an Apple M1 Max. The engine depends on the <code>memchr</code> crate, MIT OR Unlicense, for the search.</li></ul><h3 id="darudb-v1-3-0-2026-10-13" tabindex="-1">darudb v1.3.0 (2026-10-13) <a class="header-anchor" href="#darudb-v1-3-0-2026-10-13" aria-label="Permalink to &quot;darudb v1.3.0 (2026-10-13)&quot;">​</a></h3><h4 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>A database opened without a schema works with the one the file holds, as it is: its collections are reached by name, and their objects are read and written as <code>dict</code>s by the names the file stores, with the stored schema&#39;s checks and indexes kept as ever. A float field takes an int and an embedded object a <code>dict</code>, as through a class. Nothing is stored, checked or migrated, so a program can open a file whose schema it does not know. A file that holds no schema has no collections then, as before.</li><li><code>Database.stored_schema</code>, which describes the schema a database works with, the declared one or the file&#39;s own, by the names the file stores: its version, and each collection&#39;s name, primary key, whether the key is the auto-increment, fields with their types, whether each is optional and its default, and indexes. The frozen dataclasses <code>StoredSchema</code>, <code>StoredCollection</code>, <code>StoredField</code>, <code>StoredIndex</code> and <code>StoredType</code> hold it, and it is still there after the database closes.</li></ul><h4 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li><code>schema_version</code> gives the version of the file&#39;s own schema for a database opened without one, where it gave None.</li><li>Reaching a collection of a database without a schema fails with the engine&#39;s error, as in every other language: <code>INVALID_ARGUMENT</code> when the file holds no schema, or stored one after the database opened, and <code>CORRUPTED</code> or <code>UNSUPPORTED_FORMAT_VERSION</code> when the one it holds does not read. Reaching one by its class there still fails with <code>INVALID_ARGUMENT</code>.</li></ul><h3 id="darudb-v1-2-0-2026-10-11" tabindex="-1">darudb v1.2.0 (2026-10-11) <a class="header-anchor" href="#darudb-v1-2-0-2026-10-11" aria-label="Permalink to &quot;darudb v1.2.0 (2026-10-11)&quot;">​</a></h3><h4 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>A sync commit on Linux, Android and the BSDs makes the file durable with <code>fdatasync</code> rather than <code>fsync</code>, which leaves out the file&#39;s times and still syncs its length with its data. A sync commit of one object takes a quarter less time for it on a GitHub-hosted Linux runner, 312 µs against 413. macOS, iOS and Windows sync as before.</li><li>A commit asks the file system for the file&#39;s length only when its record counts pages past both the published commit&#39;s and the last one the commit wrote, rather than at every commit. A deferred commit of one object takes 11% less time for it on a GitHub-hosted Linux runner, 22.3 µs against 25.1.</li><li>A query that reads every object, as one that tests or sorts by a field without an index does, remembers where that field lies in each record it read, beside the page cache, and the next query that tests or sorts by the same field reads it there. On a GitHub-hosted Linux runner, a query of one value of such a field took a fifth less time the next time it ran, and one of the ten objects with the highest value of such a field a quarter less. A filter that is one test of one field is also made without going through the filter&#39;s tree, and compares a short string in place, which takes another tenth off such a query each time it runs. The first run takes a few percent more, and what is remembered takes up to a sixteenth more memory than the page cache&#39;s size.</li><li>An equality in a filter that is one test of one field is tested in place, rather than through a call for every object, which takes 6% off a query of one value of a field without an index in the engine.</li><li>A read transaction keeps the root of each collection and index it looks a key up in, and a key it looks up is encoded on the stack when it is a number or a short string. A lookup by primary key or by a unique field takes 8 to 9% less time for it on a GitHub-hosted Linux runner.</li><li>Reading objects, by key and through a query, reads each record straight into an instance of the class, rather than into an object of the engine first that the instance was then built from. An object read through an index takes about two fifths less time on an Apple M1 Max, and a query of 1,000 objects without an index a tenth less.</li><li><code>insert</code>, <code>put</code>, <code>insert_many</code> and <code>put_many</code> write an object of a class whose fields all hold scalars as its record, field by field, rather than as an object of the engine made by the fields&#39; names, which the engine encoded again. Inserting many objects in one write transaction takes 13 to 15% less time on an Apple M1 Max. A class with a list, an embedded object or a link is written as before.</li><li>A write transaction neither imports the module of the asynchronous API nor takes its lock to make sure no asynchronous write holds the file, while none runs in the process, and looks this thread&#39;s write transactions up once rather than three times. A one-object write transaction takes about 1.5 µs less for it on an Apple M1 Max.</li></ul><h4 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li><code>insert_many</code> and <code>put_many</code> of an asynchronous collection raise <code>DaruError</code> with <code>INVALID_ARGUMENT</code> for a batch that is not iterable, as the synchronous ones do, rather than <code>TypeError</code>.</li><li><code>backup</code> and <code>backup_async</code> refuse a <code>password_hashing</code> cost out of range with <code>INVALID_ARGUMENT</code> before they write anything, as opening does, whether a password is given or not. With a password they failed with <code>INTERNAL</code>, and without one they ignored the cost.</li></ul><h3 id="darudb-v1-1-0-2026-10-09" tabindex="-1">darudb v1.1.0 (2026-10-09) <a class="header-anchor" href="#darudb-v1-1-0-2026-10-09" aria-label="Permalink to &quot;darudb v1.1.0 (2026-10-09)&quot;">​</a></h3><h4 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h4><ul><li>The file format is version 6, <code>FORMAT_VERSION</code>, which earlier releases cannot open. Opening a file of version 5 raises it to version 6 while no other process has it open, so a file this release has opened no longer opens with 1.0, in Python or in any other language&#39;s package. An application that may go back to an earlier release, or that shares its file with a program still on one, opens with <code>upgrade_format=False</code>, which also creates new files in version 5, and calls <code>upgrade_format</code> once nothing older opens the file.</li></ul><h4 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>The <code>upgrade_format</code> parameter of <code>Database.open</code> and <code>open_async</code>, and <code>upgrade_format</code> and <code>upgrade_format_async</code>, which say whether opening raises a file of an older format version, and raise an open one.</li></ul><h4 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>An index whose entries for one value come in key order, as a non-unique index&#39;s do while the objects&#39; primary keys grow, fills its pages as it goes, where splitting a page in the middle left half of each empty, and so do the branches of every tree. A file of 400,000 sample objects with 14 indexes is 7% smaller for it. Keys in no particular order split pages evenly, as before.</li><li><code>compact</code> and <code>compact_async</code> first write again, full, every tree whose pages inserts left part empty, so that the file ends about as small as a backup&#39;s copy: the same file compacts to 119 MiB rather than 140 MiB.</li><li>File format 6 writes the lengths in a leaf&#39;s entries as varints rather than in five bytes. A file of 400,000 sample objects with 14 indexes takes 8% fewer pages, 126 MiB against 138, and compacts to 110 MiB against 119, with reads and writes as fast as before. A file raised from version 5 has only its header rewritten; its leaves take the new layout as writes change them, and <code>compact</code> rewrites the trees where that saves room.</li><li>The native module is built with its loops aligned to 64 bytes, so that where a hot loop lands no longer depends on the rest of the build: in a development build, the position of one loop alone made one-object deferred commits 15% slower. It is about 7% larger for it. The build for 64-bit Arm Windows is the exception, since the compiler cannot write that platform&#39;s unwind information for a function with padding inside it.</li></ul><h4 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li><code>compact</code> and <code>compact_async</code> no longer grow the file when a value in an overflow run near the file&#39;s end finds no run of free pages below to move into. The run stays where it is, and a round of moves that would grow the file is dropped.</li></ul><h3 id="darudb-v1-0-0-2026-10-07" tabindex="-1">darudb v1.0.0 (2026-10-07) <a class="header-anchor" href="#darudb-v1-0-0-2026-10-07" aria-label="Permalink to &quot;darudb v1.0.0 (2026-10-07)&quot;">​</a></h3><h4 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>Database.open</code> opens or creates a database file, with a <code>Schema</code> of classes decorated with <code>@collection</code>, and the options <code>create</code>, <code>page_size</code>, <code>busy_timeout</code>, <code>cache_size</code>, <code>key</code>, <code>password</code> and <code>password_hashing</code>; a <code>key</code> and a <code>password</code> together are refused with <code>INVALID_ARGUMENT</code>, here and in <code>salvage</code> and <code>backup</code>. A file holding an older schema version is migrated in one write transaction, through the <code>Migration</code>s given for the versions in between, whose <code>run</code> functions read the old objects through <code>Migrating.previous</code>.</li><li><code>@collection</code> and <code>@embedded</code> make a class a frozen, keyword-only dataclass whose annotations are its fields&#39; types: <code>bool</code>, <code>int</code>, <code>float</code>, <code>str</code>, <code>bytes</code>, lists of those, embedded classes, and any of them <code>| None</code> for an optional field. <code>field</code> adds a default, an index, a unique index, a primary key, a link to another collection, or a stored name of its own. A collection without a primary key is numbered by the engine, through its field <code>id: int | None = None</code>. An object read is built without the class&#39;s <code>__init__</code>, so a class with <code>__slots__</code> is refused.</li><li><code>db.read()</code> and <code>db.write()</code> are context managers: a write commits when its block ends, deferred with <code>durability=&quot;deferred&quot;</code>, and aborts when it raises. <code>txn.collection(User)</code> gives a collection&#39;s objects as instances of the class: <code>get</code>, <code>find</code>, <code>find_one</code> and <code>count</code>, and in a write <code>insert</code>, <code>insert_many</code>, <code>put</code>, <code>put_many</code>, <code>update</code> and <code>delete</code>. Write transactions on one file do not nest: a second one in the same thread is refused with <code>INVALID_ARGUMENT</code>, and so are <code>sync</code>, <code>close</code>, <code>compact</code> and the key changes inside one, which would wait for it.</li><li>Queries built from <code>F</code>: <code>F.age &gt;= 18</code>, <code>F.address.city == &quot;Seoul&quot;</code> through embedded objects and links, <code>between</code>, <code>is_in</code>, <code>contains</code>, <code>startswith</code>, <code>endswith</code> and null tests, combined with <code>&amp;</code>, <code>|</code> and <code>~</code>, in a <code>Query</code> with <code>where</code>, <code>sort_by</code>, <code>offset</code> and <code>limit</code>. Text in the query language with <code>$0</code>, <code>$1</code> and on, and <code>Database.prepare</code> with <code>param(0)</code> in a built query, compile a query once and run it with parameters.</li><li><code>Database.sync</code>, <code>close</code>, <code>set_key</code>, <code>set_password</code>, <code>is_encrypted</code>, <code>page_size</code>, <code>format_version</code> and <code>schema_version</code>. Every failure is a <code>DaruError</code> with the engine&#39;s error code.</li><li>The asynchronous API for <code>asyncio</code>: <code>Database.open_async</code>, <code>read_async</code>, <code>write_async</code>, <code>sync_async</code>, <code>close_async</code> and an <code>_async</code> twin of every tool and key change, which run the engine&#39;s work on a thread of the package&#39;s pool. The operations of one transaction run in the order they were called, and an event loop&#39;s asynchronous writes on one file take turns. A synchronous write, sync or close on the file from the event loop&#39;s thread while one runs, and an asynchronous one awaited inside it or in a task made inside it, are refused with <code>INVALID_ARGUMENT</code>. A migration&#39;s <code>run</code> may be a coroutine function with <code>open_async</code>.</li><li>The tools: <code>check</code>, the integrity check, which reports every problem in a <code>CheckReport</code>; <code>backup</code>, a copy of the published commit in a new file, under a new data key when it is given a <code>key</code> or a <code>password</code>; <code>compact</code>, which makes the file smaller in place; and <code>Database.salvage</code>, which rescues what it can of a damaged file into a new one.</li><li>The native module releases the GIL while the engine works, and declares itself safe for free-threaded Python.</li></ul>',35)])])}const m=o(n,[["render",i]]);export{f as __pageData,m as default};
